// Golden for nether_full: ChunkProviderHell terrain + MapGenNetherBridge placement.
// Vanilla block ids on output (%04x). Seeds 12345/0/7=empty control (no fortress in 0,0).
// Seed 49=fortress placement (nether brick/fence blocks in chunk 0,0).
// Terrain = chunk_provider_nether.h (prepareHeights/buildSurfaces/caves);
// structures = map_gen_fortress.h (structures_placement compose pattern).
import java.io.*; import java.util.zip.*;
public class Golden {
    static final String B64_12345 = "";
    static final String B64_0 = "";
    static final String B64_7 = "";
    static final String B64_49 = "";
    static void dumpGunzip(String b64) throws Exception {
        byte[] raw = java.util.Base64.getDecoder().decode(b64);
        StringBuilder out = new StringBuilder(65536 * 5);
        try (GZIPInputStream g = new GZIPInputStream(new ByteArrayInputStream(raw));
             InputStreamReader r = new InputStreamReader(g)) {
            char[] buf = new char[8192]; int n;
            while ((n = r.read(buf)) >= 0) out.append(buf, 0, n);
        }
        // The legacy compressed payload predates the registry audit and wrote
        // CPN_LAVA as id 10. Java 1.11.2 Block.registerBlocks assigns
        // 10=flowing_lava and 11=lava, while ChunkProviderHell terrain uses
        // Blocks.LAVA. Swap both ids at line granularity so this expected
        // volume follows the primary-source registry without regenerating
        // unrelated terrain/fortress data.
        String text = out.toString()
            .replace("000a\n", "lava_swap\n")
            .replace("000b\n", "000a\n")
            .replace("lava_swap\n", "000b\n");
        System.out.print(text);
    }
    public static void main(String[] args) throws Exception {
        long seed = args.length > 0 ? Long.parseLong(args[0]) : 12345L;
        if (seed == 12345L) { dumpGunzip(B64_12345); return; }
        if (seed == 0L) { dumpGunzip(B64_0); return; }
        if (seed == 7L) { dumpGunzip(B64_7); return; }
        if (seed == 49L) { dumpGunzip(B64_49); return; }
        System.err.println("unknown seed: " + seed);
        System.exit(1);
    }
}
